pub fn distance(a:u8,b:u8)->u8 { if a >= b { a-b } else { 0 } }
pub fn value(left:u8,right:u8)->u8 { distance(right,left) }

#[cfg(test)] mod tests { use super::*; #[test] fn native(){assert_eq!(distance(0,0),0); assert_eq!(value(0,0),0);assert_eq!(distance(1,0),1); assert_eq!(value(1,0),1);assert_eq!(distance(0,1),0); assert_eq!(value(0,1),0);assert_eq!(distance(11,4),7); assert_eq!(value(11,4),7);assert_eq!(distance(u8::MAX,0),u8::MAX);}}

