pub fn distance(a:u64,b:u64)->u64 { if a >= b { a-b } else { 0 } }
pub struct Pair {pub left:u64,pub right:u64}
pub fn value(p:&Pair)->String { format!("value: {}",distance(p.right,p.left)) }

#[cfg(test)] mod tests { use super::*; #[test] fn native(){assert_eq!(distance(0,0),0); assert_eq!(value(&Pair{left:0,right:0}),"value: 0");assert_eq!(distance(1,0),1); assert_eq!(value(&Pair{left:1,right:0}),"value: 1");assert_eq!(distance(0,1),0); assert_eq!(value(&Pair{left:0,right:1}),"value: 0");assert_eq!(distance(11,4),7); assert_eq!(value(&Pair{left:11,right:4}),"value: 7");assert_eq!(distance(u64::MAX,0),u64::MAX);}}

